{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "lg",
        "padding": 16
      },
      "children": [
        "title_h1",
        "divider_1",
        "group_dynamics_h2",
        "group_dynamics_text",
        "divider_2",
        "top_picks_h2",
        "game_options_stack",
        "divider_3",
        "quick_actions_h3",
        "quick_actions_stack",
        "divider_4",
        "sources_h3",
        "sources_stack"
      ]
    },
    "title_h1": {
      "type": "Text",
      "props": {
        "text": "Beginner-Friendly 6-Player Game Recommendations",
        "variant": "h1"
      },
      "children": []
    },
    "divider_1": {
      "type": "Divider",
      "props": {},
      "children": []
    },
    "group_dynamics_h2": {
      "type": "Text",
      "props": {
        "text": "Group Dynamics and Selection Criteria",
        "variant": "h2"
      },
      "children": []
    },
    "group_dynamics_text": {
      "type": "Text",
      "props": {
        "text": "These recommendations assume the group has little to no prior experience with modern hobby board games. The selections focus on high interaction, minimal downtime between turns, and rules that can be taught in under 5 minutes. The games selected bridge the gap between casual conversation and structured play, ensuring the 60-minute time limit is respected even with teaching time included.",
        "variant": "body"
      },
      "children": []
    },
    "divider_2": {
      "type": "Divider",
      "props": {},
      "children": []
    },
    "top_picks_h2": {
      "type": "Text",
      "props": {
        "text": "Top Party and Deduction Picks",
        "variant": "h2"
      },
      "children": []
    },
    "game_options_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "card_codenames",
        "card_just_one",
        "card_deception",
        "card_resistance"
      ]
    },
    "card_codenames": {
      "type": "Card",
      "props": {},
      "children": [
        "card_codenames_stack"
      ]
    },
    "card_codenames_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "codenames_h3",
        "codenames_details_stack",
        "codenames_desc",
        "codenames_button"
      ]
    },
    "codenames_h3": {
      "type": "Text",
      "props": {
        "text": "Option 1: Codenames",
        "variant": "h3"
      },
      "children": []
    },
    "codenames_details_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "wrap": "wrap"
      },
      "children": [
        "codenames_type",
        "codenames_category",
        "codenames_time"
      ]
    },
    "codenames_type": {
      "type": "Text",
      "props": {
        "text": "Team-based word association game",
        "variant": "chip"
      },
      "children": []
    },
    "codenames_category": {
      "type": "Text",
      "props": {
        "text": "Party",
        "variant": "chip"
      },
      "children": []
    },
    "codenames_time": {
      "type": "Text",
      "props": {
        "text": "15 Minutes",
        "variant": "chip"
      },
      "children": []
    },
    "codenames_desc": {
      "type": "Text",
      "props": {
        "text": "The group splits into two teams, Red and Blue. Each team has a Spymaster who provides one-word clues linked to multiple cards on the table. The goal is for teammates to guess the correct words based on the clue without picking the opposing team's words or the instant-loss Assassin card. It encourages clever thinking and group discussion.",
        "variant": "body"
      },
      "children": []
    },
    "codenames_button": {
      "type": "Button",
      "props": {
        "label": "View on BoardGameGeek"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://boardgamegeek.com/boardgame/178900/codenames"
          }
        }
      },
      "children": []
    },
    "card_just_one": {
      "type": "Card",
      "props": {},
      "children": [
        "card_just_one_stack"
      ]
    },
    "card_just_one_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "just_one_h3",
        "just_one_details_stack",
        "just_one_desc",
        "just_one_button"
      ]
    },
    "just_one_h3": {
      "type": "Text",
      "props": {
        "text": "Option 2: Just One",
        "variant": "h3"
      },
      "children": []
    },
    "just_one_details_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "wrap": "wrap"
      },
      "children": [
        "just_one_type",
        "just_one_category",
        "just_one_time"
      ]
    },
    "just_one_type": {
      "type": "Text",
      "props": {
        "text": "Cooperative guessing game",
        "variant": "chip"
      },
      "children": []
    },
    "just_one_category": {
      "type": "Text",
      "props": {
        "text": "Party",
        "variant": "chip"
      },
      "children": []
    },
    "just_one_time": {
      "type": "Text",
      "props": {
        "text": "20 Minutes",
        "variant": "chip"
      },
      "children": []
    },
    "just_one_desc": {
      "type": "Text",
      "props": {
        "text": "This is a fully cooperative game where everyone wins or loses together. One player is the guesser, and the other five write one-word clues to help them guess a specific word. The catch is that if any two players write the exact same clue, those clues are erased and the guesser never sees them. It forces players to be creative rather than obvious.",
        "variant": "body"
      },
      "children": []
    },
    "just_one_button": {
      "type": "Button",
      "props": {
        "label": "View on BoardGameGeek"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://boardgamegeek.com/boardgame/254640/just-one"
          }
        }
      },
      "children": []
    },
    "card_deception": {
      "type": "Card",
      "props": {},
      "children": [
        "card_deception_stack"
      ]
    },
    "card_deception_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "deception_h3",
        "deception_details_stack",
        "deception_desc",
        "deception_button"
      ]
    },
    "deception_h3": {
      "type": "Text",
      "props": {
        "text": "Option 3: Deception: Murder in Hong Kong",
        "variant": "h3"
      },
      "children": []
    },
    "deception_details_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "wrap": "wrap"
      },
      "children": [
        "deception_type",
        "deception_category",
        "deception_time"
      ]
    },
    "deception_type": {
      "type": "Text",
      "props": {
        "text": "Crime-solving deduction game",
        "variant": "chip"
      },
      "children": []
    },
    "deception_category": {
      "type": "Text",
      "props": {
        "text": "Social Deduction",
        "variant": "chip"
      },
      "children": []
    },
    "deception_time": {
      "type": "Text",
      "props": {
        "text": "20 Minutes",
        "variant": "chip"
      },
      "children": []
    },
    "deception_desc": {
      "type": "Text",
      "props": {
        "text": "One player is secretly the Murderer, and another is the Forensic Scientist who knows the solution but can only communicate by placing markers on scene tiles (like Cause of Death: Suffocation). The remaining players are investigators trying to interpret these vague clues to identify the murderer and the weapon used. It is less aggressive than other lying games because the focus is on the evidence.",
        "variant": "body"
      },
      "children": []
    },
    "deception_button": {
      "type": "Button",
      "props": {
        "label": "View on BoardGameGeek"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://boardgamegeek.com/boardgame/156129/deception-murder-in-hong-kong"
          }
        }
      },
      "children": []
    },
    "card_resistance": {
      "type": "Card",
      "props": {},
      "children": [
        "card_resistance_stack"
      ]
    },
    "card_resistance_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "resistance_h3",
        "resistance_details_stack",
        "resistance_desc",
        "resistance_button"
      ]
    },
    "resistance_h3": {
      "type": "Text",
      "props": {
        "text": "Option 4: The Resistance",
        "variant": "h3"
      },
      "children": []
    },
    "resistance_details_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "wrap": "wrap"
      },
      "children": [
        "resistance_type",
        "resistance_category",
        "resistance_time"
      ]
    },
    "resistance_type": {
      "type": "Text",
      "props": {
        "text": "Dystopian secret identity game",
        "variant": "chip"
      },
      "children": []
    },
    "resistance_category": {
      "type": "Text",
      "props": {
        "text": "Social Deduction",
        "variant": "chip"
      },
      "children": []
    },
    "resistance_time": {
      "type": "Text",
      "props": {
        "text": "30 Minutes",
        "variant": "chip"
      },
      "children": []
    },
    "resistance_desc": {
      "type": "Text",
      "props": {
        "text": "Players are members of a resistance group trying to overthrow a government, but spies have infiltrated the ranks. In each round, a leader proposes a team to go on a mission. Everyone votes to approve the team. If the mission goes ahead, players on the team secretly choose to Support or Sabotage the mission. The goal is to deduce who the saboteurs are based on voting patterns and mission results.",
        "variant": "body"
      },
      "children": []
    },
    "resistance_button": {
      "type": "Button",
      "props": {
        "label": "View on BoardGameGeek"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://boardgamegeek.com/boardgame/41114/the-resistance"
          }
        }
      },
      "children": []
    },
    "divider_3": {
      "type": "Divider",
      "props": {},
      "children": []
    },
    "quick_actions_h3": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h3"
      },
      "children": []
    },
    "quick_actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "button_party_games",
        "button_social_deduction"
      ]
    },
    "button_party_games": {
      "type": "Button",
      "props": {
        "label": "Browse Top Party Games"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://boardgamegeek.com/boardgamecategory/1030/party-game"
          }
        }
      },
      "children": []
    },
    "button_social_deduction": {
      "type": "Button",
      "props": {
        "label": "Browse Social Deduction"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://boardgamegeek.com/boardgamemechanic/2019/team-based-game"
          }
        }
      },
      "children": []
    },
    "divider_4": {
      "type": "Divider",
      "props": {},
      "children": []
    },
    "sources_h3": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h3"
      },
      "children": []
    },
    "sources_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "button_bgg_codenames",
        "button_bgg_just_one"
      ]
    },
    "button_bgg_codenames": {
      "type": "Button",
      "props": {
        "label": "BoardGameGeek Codenames Listing",
        "variant": "borderless"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://boardgamegeek.com/boardgame/178900/codenames"
          }
        }
      },
      "children": []
    },
    "button_bgg_just_one": {
      "type": "Button",
      "props": {
        "label": "BoardGameGeek Just One Listing",
        "variant": "borderless"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://boardgamegeek.com/boardgame/254640/just-one"
          }
        }
      },
      "children": []
    }
  }
}
